/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  var D = {"rows": [19, 14, 16, 19], "NA": 2, "NE": 6};
  phases([[0,12],[12,24],[24,46],[46,60],[60,80]]);
  v.ruleO = lin([[0,0],[3,1]]) * out; v.ruleT = 'translateY(' + lin([[0,14],[3,0]]).toFixed(1) + 'px)';
  v.aisO = lin([[14,0],[20,1]]) * out; v.entO = lin([[16,0],[22,1]]) * out;
  var nT = 0;
  for (var i = 0; i < 4; i++) { var t = 25 + i * 5, f = lin([[t,0],[t+3,1]]); v['row'+i] = f * out; if (p >= t + 1.5) nT += D.rows[i]; }
  v.accO = lin([[47,0],[51,1]]) * out; v.evO = lin([[52,0],[56,1]]) * out;
  v.resO = lin([[26,0],[29,1]]) * out;
  v.nT = nT; v.nA = p >= 49 ? D.NA : 0; v.nE = p >= 54 ? D.NE : 0;
  v.arrO = lin([[61,0],[65,1]]) * out;
  var sh = ((p * 0.9) % 7) * 6.3;
  v.arrB = 'opacity: ' + v.arrO + '; transform: translateX(' + sh.toFixed(1) + 'px);';
  v.arrT = 'opacity: ' + v.arrO + '; transform: translateX(' + (-sh).toFixed(1) + 'px);';
  v.fin = (p >= 70 && p < 97) ? out : 0;

  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
export default card;
